// code/main.js 的取数方式：只读教材底本，不手抄统计
const ZONGLUN = ['1', '2', '3', '4', '6', '7', '8'];           // 总论 7 章
const GATES = [
  { id: 'g1', name: '产地',       chapters: ['3'],    keys: ['道地', '产地'] },
  { id: 'g2', name: '采集与贮藏', chapters: ['3'],    keys: ['采收', '贮藏', '走油', '霉变'] },
  { id: 'g3', name: '炮制',       chapters: ['4'],    keys: ['炮制', '炙', '煅', '蒸'] },
  { id: 'g4', name: '配伍',       chapters: ['6'],    keys: ['相须', '相使', '相畏', '相杀', '相恶', '相反', '单行'] },
  { id: 'g5', name: '禁忌与剂量', chapters: ['7','8'], keys: ['禁用', '慎用', '十八反', '十九畏', '剂量'] },
];
// ① 规模：7 章字数/节/小节/段全部读 counts
// ② 闸：在各自教材章正文里数关键字命中
// ③ 剂量：只从第 8 章抽「数字-数字g」，不换算古制
```

第 ③ 步是本课最容易写错的地方。教材·第8章·8.1.2 虽然给了「古之一两，今用3g」这种折算参考，
但同一段也写明汉代一两约今 15.6 g、明清一两约 37 g——**三个数并存**。
所以本课只抽取教材已经写成克数的区间，不替古人做加减法：抽不到就留空，不推断。
